#' Sum daily counts to weeks
#'
#' Daily imputed counts are noisy, so sum them to weeks before comparing
#' methods.
#' Week 0 starts on day `start`.
#' Days before `start` are left out.
#' The last week may be partial.
#' It then sums the days there are.
#' A week with any `NA` day is `NA`.
#'
#' @section Warning:
#' This code was generated by an LLM.
#' Sam Abbott has only checked the interactive page.
#'
#' @param daily Daily counts.
#'   Element `i` is day `i - 1`.
#' @param start First day of week 0, a non-negative whole number.
#'   Defaults to 0.
#'
#' @return A numeric vector of weekly totals, element `w + 1` for week `w`
#'   (days `start + 7w` to `start + 7w + 6`).
#'
#' @family linelist
#' @export
#'
#' @examples
#' weekly(1:15)
#' weekly(1:15, start = 1)
#'
#' res <- impute_linelist(
#'   onset = c(0, 2, NA, 5, NA, 9),
#'   report = c(3, 6, 7, 9, 12, 13)
#' )
#' vapply(res$imputed, weekly, numeric(2))
weekly <- function(daily, start = 0) {
  if (!is.numeric(daily)) {
    stop("daily must be numeric", call. = FALSE)
  }
  start <- .check_scalar_whole(start, "start", min = 0)
  if (start >= length(daily)) {
    return(numeric(0))
  }
  daily <- daily[seq(start + 1L, length(daily))]
  week <- (seq_along(daily) - 1L) %/% 7L
  as.vector(tapply(daily, week, sum))
}
